def get_mi_cols(obj):
    """Get multiindex or index cols from a polars object."""
    return [x for x in obj.columns if isinstance(x, str) and x.startswith("__index__")]

def is_monotonically_increasing(obj):
    """Check is polars frame columns(__index__) is monotonically increasing."""
    index_cols = get_mi_cols(obj)

    # Series with no index columns
    if len(index_cols) == 0:
        return True

    # check for Series scitype
    if len(index_cols) == 1:
        if obj[index_cols[0]].is_sorted():
            return True

    # check for Panel and Hierarchical scitype
    else:
        import polars as pl

        index_df = obj.with_columns(index_cols)
        grouped = index_df.group_by(index_cols[:-1]).agg([pl.col(index_cols[-1])])
        last_index_col = grouped.select([index_cols[-1]])
        for val in last_index_col.iter_rows():
            # iter rows returns a list of tuples
            if not pl.Series(val[0]).is_sorted():
                return False
        return True

    return False

def _ret(valid, msg, metadata, return_metadata):
    """Return switch for checker functions."""
    if _metadata_requested(return_metadata):
        return valid, msg, metadata
    else:
        return valid

def _req(key, return_metadata):
    """Return whether metadata key is requested, boolean."""
    if isinstance(return_metadata, bool):
        return return_metadata
    elif isinstance(return_metadata, str) and not isinstance(key, list):
        return return_metadata == key
    elif isinstance(return_metadata, str) and isinstance(key, list):
        return return_metadata in key
    elif isinstance(return_metadata, list) and not isinstance(key, list):
        return key in return_metadata
    elif isinstance(return_metadata, list) and isinstance(key, list):
        return len(set(key).intersection(return_metadata)) > 0
    else:
        return False

def _polars_dtype_to_kind(col_dtypes):
    """Convert polars dtypes to enum DtypeKind values."""
    import polars as pl

    if isinstance(col_dtypes, list):
        return [_polars_dtype_to_kind(x) for x in col_dtypes]

    if col_dtypes.is_float():
        return DtypeKind.FLOAT
    elif col_dtypes.is_signed_integer():
        return DtypeKind.INT
    elif col_dtypes.is_unsigned_integer():
        return DtypeKind.UINT
    elif isinstance(col_dtypes, pl.Categorical) or isinstance(col_dtypes, pl.Object):
        return DtypeKind.CATEGORICAL
    elif isinstance(col_dtypes, pl.Boolean):
        return DtypeKind.BOOL
    elif col_dtypes.is_temporal():
        return DtypeKind.DATETIME
    elif isinstance(col_dtypes, pl.String):
        return DtypeKind.STRING
    else:
        raise TypeError(
            "Dtype of columns can be: INT, UINT, FLOAT, BOOL, STRING, "
            f"DATETIME, CATEGORICAL. Found dtype: {col_dtypes}"
        )

